          "content": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal inventoryHandler = {}\n\nlocal clientInventoryData = {\n\tItems = {},\n\tSize = 0,\n\tLastUpdated = 0\n}\n\nlocal currentInventoryFrame = nil\n\nlocal inventoryRemotes = ReplicatedStorage:WaitForChild(\"InventoryRemotes\")\nlocal syncInventoryRemote = inventoryRemotes:WaitForChild(\"SyncInventory\")\nlocal itemActionRemote = inventoryRemotes:WaitForChild(\"ItemAction\")\nlocal itemNotificationRemote = inventoryRemotes:WaitForChild(\"ItemNotification\")\n\nfunction inventoryHandler.GetClientInventory()\n\treturn clientInventoryData\nend\n\nfunction inventoryHandler.GetItemCount()\n\treturn #clientInventoryData.Items\nend\n\nfunction inventoryHandler.GetItemByID(itemID)\n\tfor _, item in ipairs(clientInventoryData.Items) do\n\t\tif (item.ID == itemID) then\n\t\t\treturn item\n\t\tend\n\tend\n\treturn nil\nend\n\nfunction inventoryHandler.GetItemsByType(itemType)\n\tlocal items = {}\n\tfor _, item in ipairs(clientInventoryData.Items) do\n\t\tif (item.Type == itemType) then\n\t\t\ttable.insert(items, item)\n\t\tend\n\tend\n\treturn items\nend\n \nfunction inventoryHandler.PerformItemAction(actionID, itemInstanceID)\n    itemActionRemote:FireServer(actionID, itemInstanceID)\nend\n\nfunction inventoryHandler.SetCurrentInventoryFrame(frame)\n    currentInventoryFrame = frame\nend\n\nfunction inventoryHandler.ShowItemNotification(item, actionText)\n    if (currentInventoryFrame and currentInventoryFrame.showNotification) then\n        currentInventoryFrame.showNotification(item, actionText)\n    end\nend\n\nfunction inventoryHandler.RefreshInventoryDisplay()\n    if (currentInventoryFrame and currentInventoryFrame.refreshCurrentPage) then\n        currentInventoryFrame.refreshCurrentPage()\n    end\nend\n\nsyncInventoryRemote.OnClientEvent:Connect(function(inventoryData)\n\tif (inventoryData and type(inventoryData) == \"table\") then\n\t\tlocal previousItemCount = #clientInventoryData.Items\n\t\tclientInventoryData = inventoryData\n\t\tlocal newItemCount = #clientInventoryData.Items\n\t\t\n\t\tprint(\"Inventory synced from server. Items:\", newItemCount)\n\n\t\tinventoryHandler.RefreshInventoryDisplay()\n\tend\nend)\n\nitemNotificationRemote.OnClientEvent:Connect(function(item, actionText)\n    if (item and actionText) then\n        inventoryHandler.ShowItemNotification(item, actionText)\n    end\nend)\n\nreturn inventoryHandler"
