          "content": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal CurrencyHandler = {}\nlocal currency = {}\n\nlocal currencyUpdateEvent = ReplicatedStorage:WaitForChild(\"CurrencyUpdate\")\ncurrencyUpdateEvent.OnClientEvent:Connect(function(currencyId, amount)\n\tcurrency[currencyId] = amount\n    print(\"Currency updated:\", currencyId, amount)\nend)\n\nfunction CurrencyHandler.getCurrency(currencyId)\n\tif (currency[currencyId]) then\n\t\treturn currency[currencyId]\n\tend\n\treturn 0\nend\n\nreturn CurrencyHandler"
