          "content": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal UserGroupHandler = {}\nlocal userGroupsData = {}\nlocal allGroupsData = {}\nlocal userGroupRemote\n\nlocal function waitForRemote()\n\tuserGroupRemote = ReplicatedStorage:WaitForChild(\"UserGroupRemote\")\nend\n\nlocal function onUserGroupDataReceived(data)\n\tif (data.userGroups) then\n\t\tuserGroupsData = data.userGroups\n\tend\n\tif (data.allGroups) then\n\t\tallGroupsData = data.allGroups\n\tend\n\tlocal PlayerListUI = script.Parent.Parent.PlayerList.PlayerListUI\n\tif (PlayerListUI) then\n\t\tlocal success, module = pcall(require, PlayerListUI)\n\t\tif (success and module.UpdatePlayerGroups) then\n\t\t\tmodule.UpdatePlayerGroups()\n\t\tend\n\tend\nend\n\nfunction UserGroupHandler.getUserGroup(player)\n\tif (not player) then\n\t\treturn nil\n\tend\n\tlocal userId = tostring(player.UserId)\n\tlocal groupId = userGroupsData[userId]\n\tif (groupId and allGroupsData[groupId]) then\n\t\treturn allGroupsData[groupId]\n\tend\n\treturn nil\nend\n\nfunction UserGroupHandler.getUserGroupById(userId)\n\tif (not userId) then\n\t\treturn nil\n\tend\n\tlocal userIdStr = tostring(userId)\n\tlocal groupId = userGroupsData[userIdStr]\n\tif (groupId and allGroupsData[groupId]) then\n\t\treturn allGroupsData[groupId]\n\tend\n\treturn nil\nend\n\nfunction UserGroupHandler.getUserGroupName(player)\n\tlocal group = UserGroupHandler.getUserGroup(player)\n\tif (group and group.name) then\n\t\treturn group.name\n\tend\n\treturn nil\nend\n\nfunction UserGroupHandler.getUserGroupConfig(player)\n\tlocal group = UserGroupHandler.getUserGroup(player)\n\tif (group and group.config) then\n\t\treturn group.config\n\tend\n\treturn nil\nend\n\nfunction UserGroupHandler.getUserGroupColor(player)\n\tlocal config = UserGroupHandler.getUserGroupConfig(player)\n\tif (config and config.ColorGradient) then\n\t\treturn config.ColorGradient\n\tend\n\tif (config and config.Color) then\n\t\treturn config.Color\n\tend\n\treturn nil\nend\n\nfunction UserGroupHandler.hasPermission(player, permission)\n\tlocal config = UserGroupHandler.getUserGroupConfig(player)\n\tif (config and config.Permissions and config.Permissions[permission]) then\n\t\treturn true\n\tend\n\treturn false\nend\n\nfunction UserGroupHandler.getAllUserGroups()\n\tlocal groups = {}\n\tfor id, group in pairs(allGroupsData) do\n\t\ttable.insert(groups, {\n\t\t\tid = id,\n\t\t\tname = group.name,\n\t\t\tconfig = group.config\n\t\t})\n\tend\n\treturn groups\nend\n\nfunction UserGroupHandler.Init()\n\twaitForRemote()\n\tuserGroupRemote.OnClientEvent:Connect(onUserGroupDataReceived)\nend\n\nreturn UserGroupHandler"
